static int countSum(int[] a, int k) {
    int n = a.length, cnt = 0;
    int full = 1 << n;
    for (int mask = 0; mask < full; mask++) {
        int s = 0;
        for (int i = 0; i < n; i++)
            if ((mask & (1 << i)) != 0)
                s += a[___];
        if (s == k) cnt++;
    }
    return cnt;
}

